mapper.select:
SELECT  FROM ifj_event_wait
WHERE instance_id = #{instanceId}
ORDER BY attempt_no DESC, id DESC LIMIT 1

        SELECT * FROM (

        SELECT  FROM ifj_event_wait
        WHERE instance_id = #{instanceId}
        ORDER BY attempt_no DESC, id DESC
        ) WHERE ROWNUM <= 1

SELECT operator_id FROM ifj_event_wait_operator
WHERE wait_id = #{waitId}
ORDER BY operator_id ASC

SELECT wait_record.id, wait_record.instance_id, wait_record.root_instance_id, wait_record.wait_type, wait_record.status, wait_record.event_code, wait_record.business_key, wait_record.correlation_key, wait_record.accept_after, wait_record.timeout_at, wait_record.matched_event_id, wait_record.decision_by, wait_record.decision_comment, wait_record.resolved_at, wait_record.create_time, wait_record.update_time, FROM ifj_event_wait wait_record
WHERE wait_record.wait_type = 'APPROVAL' AND EXISTS ( SELECT 1 FROM ifj_event_wait_operator wait_operator WHERE wait_operator.wait_id = wait_record.id AND wait_operator.operator_id = #{operatorId} )
AND wait_record.status = #{query.status}
AND wait_record.instance_id = #{query.instanceId}
AND wait_record.root_instance_id = #{query.rootInstanceId}
AND LOWER(task_snapshot.name) LIKE LOWER(#{query.taskNamePattern}) ESCAPE '!'
ORDER BY wait_record.create_time DESC, wait_record.id DESC

SELECT  FROM ifj_event_wait
WHERE status = 'WAITING' AND timeout_at IS NOT NULL
  AND timeout_at <= #{now}
ORDER BY timeout_at ASC, id ASC LIMIT #{limit}

        SELECT * FROM (

        SELECT  FROM ifj_event_wait
        WHERE status = 'WAITING' AND timeout_at IS NOT NULL
          AND timeout_at <= #{now}
        ORDER BY timeout_at ASC, id ASC
        ) WHERE ROWNUM <= #{limit}

SELECT TOP (1)  FROM ifj_event_wait
WHERE instance_id = #{instanceId}
ORDER BY attempt_no DESC, id DESC
